        new Quote { Id = "https://en.wikiquote.org/wiki/Emily_Chang", Text = "I love what I do. I love getting to talk with these people, and I feel like I'm learning something every day. You also have to be a really good listener, which I think is an underestimated skill", Author = "Emily Chang" },
