        new Quote { Id = "https://en.wikiquote.org/wiki/Ratchet_%26_Clank_Future%3A_Tools_of_Destruction", Text = "[After crashing hoverbike] Well, looks like we're going on foot. At least I can try out my new nav-unit.", Author = "Ratchet & Clank Future: Tools of Destruction" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Malika_Hachid", Text = "I was first deputy director, then director. But in fact, that’s not at all what I wanted to do.", Author = "Malika Hachid" },
