        new Quote { Id = "https://en.wikiquote.org/wiki/Laila_Iskander", Text = "In parallel, we have been taking steps to expand our use of modern methods of irrigation to maximise our efficient use of water.", Author = "Laila Iskander" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Talented_Mr._Ripley_%28film%29", Text = "If I could just go back... if I could rub everything out... starting with myself.", Author = "The Talented Mr. Ripley (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Louis_Bromfield", Text = "Truth may be found in the heart of a philosopher but seldom in the figures of a statistician; it is far too delicate a thing to be pinned down to columns of numbers on ruled paper.", Author = "Louis Bromfield" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Inonge_Wina", Text = "It was a privilege for me, but it also had the benefit of renewing the ambitions of young women in my country.", Author = "Inonge Wina" },
