        new Quote { Id = "https://en.wikiquote.org/wiki/Zipporah_Kittony", Text = "The women of Kenya have made Kenya proud through our athletes, the late Wangari Maathai, and the rest. I am so overjoyed because the women have done it.", Author = "Zipporah Kittony" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Mask_of_Zorro", Text = "You know there is a saying, a very old saying: when the pupil is ready the master will appear.", Author = "The Mask of Zorro" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mia_le_Roux", Text = "I believe I deserve to win the title as I embody resilience, strength and the ubuntu spirit within South Africa. As a deaf woman with a cochlear implant, I represent a community that often goes unheard.", Author = "Mia le Roux" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Steltzner", Text = "If you come up with a big new idea in our world and everyone says Hey, that's great, definitely go ahead with that, then you know it's not a big new idea at all. Anything really new brings out all the reasons why it can't possibly work, and why it's crazy to even think about it.", Author = "Adam Steltzner" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Matthieu_Ricard", Text = "We must distinguish between spirituality in general terms, which aims to make us better people, and religion. Adopting a religion remains optional, but becoming a better human being is essential.", Author = "Matthieu Ricard" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bo%C5%BEe_Rado%C5%A1", Text = "Caritas is one big family made up primarily of little people with a big heart, who help those who are in a more difficult situation than we are. These people are our faithful, but also many people of good will in Croatia and in our diaspora.", Author = "Bože Radoš" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Saint_Nimatullah_Kassab", Text = "A monk's first concern, night and day, should be not to hurt or trouble his brother monks.", Author = "Saint Nimatullah Kassab" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rose_Marie_Toussaint", Text = "When we are rejected in the world, we will recover only as we begin to realize that we must hold on to our sense of who we are and not be defeated by outside evaluations.", Author = "Rose Marie Toussaint" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Enriqueta_Vasquez", Text = "When the article, The Woman of La Raza came out as a result of the 1969 Chicano Conference, I experienced repercussions because I wrote about The Woman. Instead of being intimidated, I felt it necessary to write a whole book on La Mujer.", Author = "Enriqueta Vasquez" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Purple_Violet_of_Oshaantu", Text = "Well, I'm sorry you all feel uncomfortable about mybehaviour, but I cannot pretend. I cannot lie to myself and everybody else in this village", Author = "The Purple Violet of Oshaantu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wu_Chun", Text = "Life is short, be grateful, be kind, be happy. Forgive and forget ... Love and peace.", Author = "Wu Chun" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Derek_Jarman", Text = "People say to me, You make fantastic films and I say, No, I make documentaries.", Author = "Derek Jarman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sabina_Franklyn", Text = "It was very difficult not to want to go into acting because it is in my blood and I still feel to this day that a dressing room is like another home.", Author = "Sabina Franklyn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Daniel_Handler", Text = "For Beatrice--Darling, dearest, dead.", Author = "Daniel Handler" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ethan_Allen", Text = "The gods of the valley are not the gods of the hills, and you shall understand it.", Author = "Ethan Allen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jessamyn_West_%28writer%29", Text = "Only a fool would refuse to enter a fool's paradise — when that's the only paradise he'll ever have a chance to enter.", Author = "Jessamyn West (writer)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Carla_Harris", Text = "As senior women in your organizations, every single one of you in this room has influence,", Author = "Carla Harris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Asher_Peres", Text = "Quantum phenomena do not occur in a Hilbert space. They occur in a laboratory.", Author = "Asher Peres" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Emma_Walmsley", Text = "People regret far more what they don’t do rather than what they do.", Author = "Emma Walmsley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lien_Fang_Yu", Text = "We can have think tanks on both sides of the Taiwan Strait to start to explore problems that still exist in the political area.", Author = "Lien Fang Yu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paddington_2", Text = "Dear Aunt Lucy, you sent me to London to find a home. I have a wonderful family. I've really got to grips with how things work.", Author = "Paddington 2" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yvonne_Okwara_Matole", Text = "All mothers like everyone else should have equal opportunity in this country", Author = "Yvonne Okwara Matole" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Legally_Blonde_2%3A_Red%2C_White_and_Blonde", Text = "This is just like CSpan, except I'm not bored.", Author = "Legally Blonde 2: Red, White and Blonde" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Farkhonda_Hassan", Text = "The objective now is not to renegotiate our dreams, but to emphasize the accountability of all actors through detailed discussions of goals, targets, achievements and failures. We are no longer seeking promises, but are demanding action.", Author = "Farkhonda Hassan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sheryl_Sandberg", Text = "If we could get to a place of true equality, where what we do in life is determined not by gender but by our passions and interests, our companies would be more productive and our home lives not just better balanced but happier.", Author = "Sheryl Sandberg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stonewall_Jackson", Text = "The time for war has not yet come, but it will come and that soon; and when it does come my advice is to draw the sword and throw away the scabbard.", Author = "Stonewall Jackson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/She-Wolf_of_London_%28film%29", Text = "Phyllis Allenby: I feel terribly sleepy as if I'd been drugged.\nMartha Winthrop: You're right. I drugged you.\nPhyllis Allenby: So I wouldn't hear the dogs?\nMartha Winthrop: No Phyllis. I'm going to kill you.", Author = "She-Wolf of London (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Burnet_Wright", Text = "Blessedness, he affirmed, comes not from outward conditions but from inward states. It consists not in positions, but in dispositions.", Author = "William Burnet Wright" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kariamanickam_Srinivasa_Krishnan", Text = "This elegant generalization is mathematically very appealing; but physics means facing facts. You should take up case by case.", Author = "Kariamanickam Srinivasa Krishnan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Stasheff", Text = "But revolutionaries are always out of place when the revolution is over, and are likely to prove an embarrassing factor to the police forces of the new government.", Author = "Christopher Stasheff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ogden_Rood", Text = "The advance from drawing to painting should be gradual , and no serious attempts in colour should be made until the student has obtained proficiency in outline and in light and shade. If the artist cannot draws objects in a rather masterly way there is no point in his attempting colour.", Author = "Ogden Rood" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bolaji_Akinboro", Text = "My ventures consistently bridge the gap between global innovation and local realities, proving that true progress must be inclusive, sustainable, and culturally relevant.", Author = "Bolaji Akinboro" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marianna_Dushar", Text = "Food, like language, is the first and last cultural bastion. We grow up with it, and we associate ourselves with it. Countries communicate with other countries through food.", Author = "Marianna Dushar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Four_Quartets", Text = "Time present and time past Are both perhaps present in time future And time future contained in time past.", Author = "Four Quartets" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eyes_of_Wakanda", Text = "Lion: You are not one of them. You are meant to roam free. Like me!\nNoni: I am not like you.", Author = "Eyes of Wakanda" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Caitlin_Davies", Text = "I’ve never thought of myself as a cultural activist, but thanks! The reason I work in different fields is mainly to make a living – professional authors in the UK now earn an average of around £10,000 a year, it’s usually impossible to live just from writing books.", Author = "Caitlin Davies" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Subhas_Chandra_Bose", Text = "Give me blood and I will give you freedom.", Author = "Subhas Chandra Bose" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ra%C3%BAl_Horacio_Scarrone_Carrero", Text = "Many parishes, communities and groups live their faith but they feel no call to share it. Many Christians, including convinced and practising ones, are completely unaware of their responsibility to announce and share their faith with others", Author = "Raúl Horacio Scarrone Carrero" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_John_Byrne", Text = "I'm humbled, but if this is what God wants, if he kicks the ball in your direction, you might as well run with it. I honestly never thought about it for a minute before it happened that I would be named a bishop. I was surprised myself.", Author = "Peter John Byrne" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chiara_Scelsi", Text = "Diventare modella non era un sogno ma un obiettivo. Per avere soldi e poter pensare ai sogni.", Author = "Chiara Scelsi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mechthild_of_Magdeburg", Text = "What we know is as nothing, if we do not love God properly in all things.", Author = "Mechthild of Magdeburg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jacob_Thoomkuzhy", Text = "Knowing nature closely and intimately enhances faith. So loving and caring for nature is a way of protecting your faith.", Author = "Jacob Thoomkuzhy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Bryant_%28bowls%29", Text = "I'm not an athlete, more a gymnast and golfer, soldered together.", Author = "David Bryant (bowls)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elayne_Arrington", Text = "It was surreal watching the movie", Author = "Elayne Arrington" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gospel_of_Thomas", Text = "Let him who seeks continue seeking until he finds. When he finds, he will become troubled. When he becomes troubled, he will be astonished, and he will rule over the All.", Author = "Gospel of Thomas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rebecca_Lim", Text = "The only thing I can say is, I'm not someone who draws a very clear line. I'm actually a very forgiving person. Once the trust is broken, it's difficult for me to mend the trust. I'm also someone who really believes that action speaks louder than words.", Author = "Rebecca Lim" },
        new Quote { Id = "https://en.wikiquote.org/wiki/August_Heckscher_II", Text = "In one sense freedom is always in crisis, just as beauty is, and honor and truth-all those things which man has made for himself as a garment against the ever-present blasts of the barbarian spirit,", Author = "August Heckscher II" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Leopold_Stokowski", Text = "I understand you are doing The Sorcerer's Apprentice. I would love to do that for you. I will do it for nothing.", Author = "Leopold Stokowski" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Otto_Weininger", Text = "The highest expression of all morality is: Be!", Author = "Otto Weininger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Angela_Makholwa", Text = "I think i just love danger", Author = "Angela Makholwa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Samuel_Richardson", Text = "O! what a Godlike Power is that of doing Good! — I envy the Rich and the Great for nothing else!", Author = "Samuel Richardson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Madeleine_L%27Engle", Text = "Inspiration usually comes during work, rather than before it.", Author = "Madeleine L'Engle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Iran-Contra_affair", Text = "The simple truth is, 'I don't remember — period.'", Author = "Iran-Contra affair" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jules_Feiffer", Text = "It is not size or age or childishness that separates children from adults. It is responsibility.", Author = "Jules Feiffer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lloyd_Russell-Moyle", Text = "I wasn't going to struggle with someone wearing a huge sword on their hip.", Author = "Lloyd Russell-Moyle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Too_Big_to_Fail_%28film%29", Text = "We're late. We've been late on everything.", Author = "Too Big to Fail (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francisco_Garc%C3%ADa_Diego_y_Moreno", Text = "The bishop began with great plans and a sincere desire to promote the welfare of the Church in his territory.", Author = "Francisco García Diego y Moreno" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Daniel_S._Hamermesh", Text = "The creation of economic stories from real life is an ongoing process—because new stories appear every day.", Author = "Daniel S. Hamermesh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/George_Meredith", Text = "First of earthly singers, the sun-loved rill.", Author = "George Meredith" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Smart", Text = "Too hard for any frog's digestion,To have his froghood call'd in question!", Author = "Christopher Smart" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rumman_Chowdhury", Text = "I always say I’m not born of tech. I did not start my career in tech — I began working at nonprofits, public policy organizations, and even as an economist. That breadth of experience gives me a perspective on technology that goes beyond the usual tech world.", Author = "Rumman Chowdhury" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Beyond_the_Sea_%28film%29", Text = "[voice over] Momma was right about music. It opened a whole new world to me, outside of time and illness. The world I could live in.", Author = "Beyond the Sea (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gofaone_Mabutho", Text = "Hit the ground running", Author = "Gofaone Mabutho" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michael_Oakeshott", Text = "Whatever is satisfactory in experience is true, and it is true because it is satisfactory.", Author = "Michael Oakeshott" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stephen_Fumio_Hamao", Text = "Peace never occurs in isolation. It is the fruition of a good life for all. For that reason, working for peace is considered to be a highly esteemed spiritual value. Peace is the greatest blessing of God to a people. Working for peace should be a central concern of the Church.", Author = "Stephen Fumio Hamao" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sonic_the_Hedgehog", Text = "I'll show you what true speed REALLY is!", Author = "Sonic the Hedgehog" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Sanders_Peirce", Text = "True science is distinctively the study of useless things. For the useful things will get studied without the aid of scientific men.", Author = "Charles Sanders Peirce" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Watch", Text = "You've been planning an alien invasion... in my Costco?", Author = "The Watch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Xenocide", Text = "The wise are not wise because they make no mistakes. They are wise because they correct their mistakes as soon as they recognize them.", Author = "Xenocide" },
        new Quote { Id = "https://en.wikiquote.org/wiki/M._S._Swaminathan", Text = "Agriculture is the backbone of the livelihood security system of nearly 700 million people in the country and we need to build our food security on the foundation of home grown food.", Author = "M. S. Swaminathan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edward_Joseph_Weisenburger", Text = "I am impressed by the way God created this world. The damage can be repaired in many instances. But we have to pull together and we have to be responsible. We have an obligation not to destroy just for the sake of today or for the sake of destroying.", Author = "Edward Joseph Weisenburger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Esther_Friesner", Text = "Pigs possess a certain native intelligence and common sense by and large missing from our greater poets. When despair lays its clammy paws across their fevered porcine brows, they do not slump about composing sonnets; they take action.", Author = "Esther Friesner" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Batya_Friedman", Text = "We’re fast and furious with these technologies that are at a scale and power that’s beyond our current moral capacities, I think right now we have a really great mismatch between the power of our tools and our wisdom to use them well.", Author = "Batya Friedman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hardcore_punk", Text = "Defining hardcore is like defining falling in love -- definitions really miss the point. You don't need a definition to know if you're in love or not -- you just know it. You just feel real hardcore when you experience it.", Author = "Hardcore punk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anabel_Abarca", Text = "Our ward is filled with motivated and passionate people who see our community’s potential, and I look forward to bringing their vision to life as alderwoman. Together we will make the 12th Ward strong and ensure every neighbor thrives.", Author = "Anabel Abarca" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ashley_Biden", Text = "Any achievement that I accomplished, many people attributed to the fact that I was his daughter", Author = "Ashley Biden" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gaylon_Alcaraz", Text = "There were only about 30 Black kids in my class. It was the 1980s and there was still a lot of racism, a lot of isolation, separation. I remember being targeted in certain classes,", Author = "Gaylon Alcaraz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Dickey", Text = "I was standing in the most absolute aloneness that I had ever been given.", Author = "James Dickey" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lere_Paimo", Text = "When you stand in the way of someone’s daily bread, you have sentenced the person to death.", Author = "Lere Paimo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lahiri_Mahasaya", Text = "By serving wise and ignorant sadhus, I am learning the greatest of virtues, pleasing to God above all others — humility.", Author = "Lahiri Mahasaya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Samuel_Paterson", Text = "Books, like friends, should be few and well chosen.", Author = "Samuel Paterson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gordon_R._Dickson", Text = "Even as she lay dreaming these dreams, however, a sane part of her mind was still on duty. Realistically, she knew that what she was thinking was nonsense.", Author = "Gordon R. Dickson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Skyfall", Text = "[re. the porcelain bulldog on M's desk.] The whole office goes up in smoke and that bloody thing survives?", Author = "Skyfall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dumi_Mkokstad", Text = "My dad is a pastor, and my mom is a pastor’s wife. Both my parents are quite musical.", Author = "Dumi Mkokstad" },
        new Quote { Id = "https://en.wikiquote.org/wiki/From_Here_to_Eternity", Text = "Pvt. Prewitt: A man don't go his own way, he's nothing.\nSgt. Warden: Maybe back in the days of the pioneers a man could go his own way, but today you got to play ball.", Author = "From Here to Eternity" }
    };
